properties.query:
let windowSize = 2h;

// S34: Recon/Credential Probe (연결키: Operator)
let S34 =
    UAVOpAudit_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType == 'login_failure';
// S96: Crypto Key Exfil — UAVSatcomLink_CL엔 Operator/UAVId 결합만 존재, 전역 게이트로 대리 사용 (고엔트로피 페이로드)
let S96Time = toscalar(
    UAVSatcomLink_CL
    | where TimeGenerated > ago(windowSize)
    | where PayloadEntropy > 7.5 and PayloadBytes > 0
    | summarize min(TimeGenerated));
// S92: Exfil (SAR/Auth) — UAVSarPayload_CL, 전역 게이트
let S92Time = toscalar(
    UAVSarPayload_CL
    | where TimeGenerated > ago(windowSize)
    | where SizeBytes > 0
    | summarize min(TimeGenerated));
S34
| extend HasS96 = isnotnull(S96Time), HasS92 = isnotnull(S92Time)
| where HasS96 or HasS92
| extend CampaignType = "C11_자격증명_암호키유출_인증유출"
| extend StepSummary = strcat("S34@", tostring(TimeGenerated), " | S96(전역)@", tostring(S96Time), " | S92(전역)@", tostring(S92Time))
| extend Severity = "High"
| project TimeGenerated, S96Time, S92Time, Operator, CampaignType, StepSummary, Severity
